'use strict';
const $=s=>document.querySelector(s), $$=s=>Array.from(document.querySelectorAll(s));
const esc=v=>String(v==null?'':v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const uid=()=>crypto.randomUUID().replace(/-/g,'');
const moneyFormat=new Intl.NumberFormat('th-TH',{minimumFractionDigits:2,maximumFractionDigits:2});
const baht=n=>moneyFormat.format((n||0)/100);
const cash=n=>'฿'+baht(n);
const thaiDate=d=>new Date(d+'T00:00:00+07:00').toLocaleDateString('th-TH',{day:'numeric',month:'short',year:'numeric'});
const monthLabel=m=>new Date(m+'-01T00:00:00+07:00').toLocaleDateString('th-TH',{month:'long',year:'numeric'});
const SOURCE={manual:'กรอกเอง',slip:'จากสลิป',recurring:'รายการประจำ'};
let S=emptyState_(),meta={},page='dashboard',month='',filters={type:'all',category:'',q:''},chartMode='day',avatarCache={},welcome={name:'',occupations:[],expectedIncome:0,savingPercent:20,avatarId:''},welcomeStep=1;
let debtFilter='',dismissedDebtAlert='';
let activeDrafts=[],draftImages=[],retainImages=true;
function rpc(action,payload={}){if(window.PREVIEW_API)return window.PREVIEW_API(action,payload);return new Promise((resolve,reject)=>{google.script.run.withSuccessHandler(resolve).withFailureHandler(e=>reject(new Error(e.message||'เชื่อมต่อไม่สำเร็จ'))).api(action,payload);});}
function toast(message){$('#toast').textContent=message;$('#toast').style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').style.display='none',5000);}
async function safely(fn,el){if(el?.disabled)return;try{if(el)el.disabled=true;await fn();}catch(e){toast(e.message||String(e));}finally{if(el)el.disabled=false;}}
function applySnapshot(data){meta=data;S=data.state;month=month||meta.today.slice(0,7);applyTheme();render();}
async function reload(){applySnapshot(await rpc('load'));}
function applyTheme(){const theme=S.Settings.main?.theme||'dark';document.body.classList.toggle('light',theme==='light'||(theme==='system'&&matchMedia('(prefers-color-scheme: light)').matches));}
matchMedia('(prefers-color-scheme: light)').addEventListener('change',applyTheme);
function icon(c){return `<span class="cat-icon" style="background:${esc(c?.color||'#93a5b6')}20">${esc(c?.icon||'📦')}</span>`;}
function cat(id){return S.Categories[id]||{name:'หมวดเดิม',icon:'📦',color:'#93a5b6'};}
function empty(message){return `<div class="empty"><span>✧</span>${esc(message)}</div>`;}
function progress(n,over){return `<div class="progress"><i style="width:${Math.min(100,Math.max(0,n||0))}%;background:${over?'var(--red)':'var(--green)'}"></i></div>`;}
function monthInput(){return `<input id="monthPicker" class="month" aria-label="เลือกเดือน" type="month" min="2000-01" max="2099-12" value="${month}">`;}
function heading(title,sub){return `<div class="pagehead"><div><div class="eyebrow">${esc(sub)}</div><h1>${esc(title)}</h1></div>${monthInput()}</div>`;}
function field(label,name,value,type='text',extra=''){return `<label class="field"><span>${esc(label)}</span><input name="${name}" type="${type}" value="${esc(value)}" ${extra}></label>`;}
function selectField(label,name,options,value){return `<label class="field"><span>${esc(label)}</span><select name="${name}">${options.map(x=>`<option value="${esc(x[0])}" ${x[0]===value?'selected':''}>${esc(x[1])}</option>`).join('')}</select></label>`;}
function moneyField(label,name,n,zero=true){return field(label,name,n? (n/100).toFixed(2):'','number',`placeholder="0.00" min="${zero?'0':'0.01'}" max="1000000000" step="0.01" ${zero?'':'required'} inputmode="decimal"`);}
function satang(v){const s=String(v??'').trim()||'0';if(!/^\d+(\.\d{1,2})?$/.test(s))throw new Error('จำนวนเงินต้องเป็นบวกและทศนิยมไม่เกิน 2 ตำแหน่ง');const [a,b='']=s.split('.');return Number(a)*100+Number(b.padEnd(2,'0'));}
function fd(form){return Object.fromEntries(new FormData(form));}
function bindForm(id,fn){const form=$('#'+id);form.addEventListener('input',()=>delete form.dataset.requestId);form.onsubmit=e=>{e.preventDefault();safely(()=>fn(fd(form),form),form.querySelector('[type=submit]'));};}
function modal(title,html){$('#modalTitle').textContent=title;$('#modalBody').innerHTML=html;if(!$('#modal').open)$('#modal').showModal();$('#modal').scrollTop=0;}
function closeModal(){$('#modal').close();}
async function save(table,id,value,form,remove=false){
  const requestId=form?.dataset.requestId||uid();if(form)form.dataset.requestId=requestId;
  const result=await rpc('mutate',{requestId,table,id,revision:S[table][id]?.revision||0,value,remove});if(result.snapshot)applySnapshot(result.snapshot);else await reload();toast(remove?'ลบข้อมูลแล้ว':'บันทึกแล้ว');
}
async function removeEntity(table,id){if(!confirm('ยืนยันลบรายการนี้? ประวัติการแก้ไขยังคงอยู่ในฐานข้อมูล'))return;await save(table,id,null,null,true);closeModal();}
function render(){
  if(!S.Users.main?.onboarded){$('#nav').hidden=true;renderWelcome();return;}$('#nav').hidden=false;
  const views={dashboard:dashboard,transactions:transactions,budget:budgetPage,debts:debtsPage,history:historyPage,profile:profilePage,recurring:recurringPage,categories:categoriesPage};
  $('#main').innerHTML=(views[page]||dashboard)();$$('[data-page]').forEach(b=>{b.classList.toggle('active',b.dataset.page===page);b.onclick=()=>go(b.dataset.page);});
  $('#monthPicker')?.addEventListener('change',e=>{if(e.target.value){month=e.target.value;render();}});
  $$('[data-tx]').forEach(b=>b.onclick=()=>editTransaction(S.Transactions[b.dataset.tx]));
  $$('[data-cat-filter]').forEach(b=>b.onclick=()=>{filters.category=b.dataset.catFilter;filters.type='all';go('transactions');});
  $$('[data-pay]').forEach(b=>b.onclick=()=>payDebt(S.Debts[b.dataset.pay]));
  $$('[data-edit-debt]').forEach(b=>b.onclick=()=>editDebt(S.Debts[b.dataset.editDebt]));
  $$('[data-rec]').forEach(b=>b.onclick=()=>editRecurring(S.Recurring[b.dataset.rec]));
  $$('[data-edit-cat]').forEach(b=>b.onclick=()=>editCategory(S.Categories[b.dataset.editCat]));
  bindPage();loadAvatar();debtReminder();
}
function go(p){page=p;render();window.scrollTo({top:0,behavior:'smooth'});$('#main').focus({preventScroll:true});}
async function loadAvatar(){const id=S.Users.main?.avatarId;const b=$('#profileButton');b.textContent=S.Users.main?.name?.slice(0,1)||'☺';if(!id)return;try{if(!avatarCache[id])avatarCache[id]=(await rpc('file',{id})).url;if(S.Users.main?.avatarId===id)b.innerHTML=`<img alt="รูปโปรไฟล์" src="${avatarCache[id]}">`;const pic=$('#profilePhoto');if(pic){pic.src=avatarCache[id];pic.hidden=false;}}catch(e){/* Profile stays usable if Drive image has been removed. */}}
function txRows(rows){return rows.length?rows.map(t=>`<button class="tx" data-tx="${esc(t.id)}">${icon(cat(t.category))}<span class="grow"><b>${esc(t.title)}</b><small>${thaiDate(t.date)} · ${esc(t.time)} · ${SOURCE[t.source]||'กรอกเอง'}</small></span><span class="value ${t.type==='income'?'positive':t.type==='expense'?'negative':'accent'}">${t.type==='income'?'+':t.type==='expense'?'−':'↔'}${baht(t.amount)}<small>${t.status==='forecast'?'◷ รอยืนยัน':'บาท'}</small></span></button>`).join(''):empty('ยังไม่มีรายการ ลองเพิ่มรายการแรกของคุณ');}
function sortedRows(){return values_(S,'Transactions').filter(t=>t.date.slice(0,7)===month).sort((a,b)=>(b.date+b.time).localeCompare(a.date+a.time));}
function donut(type,title){const rows=actual_(S,month).filter(t=>t.type===type),sum=total_(rows),cs=values_(S,'Categories').filter(c=>c.type===type).map(c=>({c,n:total_(rows.filter(t=>t.category===c.id))})).filter(x=>x.n>0).sort((a,b)=>b.n-a.n);let offset=0;
  const circles=cs.map(({c,n})=>{const pct=n/sum*100,result=`<circle cx="60" cy="60" r="48" fill="none" stroke="${c.color}" stroke-width="12" pathLength="100" stroke-dasharray="${pct} ${100-pct}" stroke-dashoffset="${-offset}"/>`;offset+=pct;return result;}).join('');
  return `<section class="card"><div class="cardhead"><h2>${title}</h2><span class="pill">${cs.length} หมวด</span></div>${sum?`<div class="donut-layout"><div class="donut"><svg viewBox="0 0 120 120" role="img" aria-label="${title}"><circle cx="60" cy="60" r="48" fill="none" stroke="var(--surface)" stroke-width="12"/>${circles}</svg><div class="donut-center"><small>รวมทั้งเดือน</small><b>${cash(sum)}</b></div></div><div class="donut-legend">${cs.map(({c,n})=>`<button class="legend-row" data-cat-filter="${c.id}">${icon(c)}<span class="grow">${esc(c.name)}</span><span class="value"><b>${(n/sum*100).toFixed(1)}%</b><small style="display:block">${cash(n)}</small></span></button>`).join('')}</div></div>`:empty('ยังไม่มี'+(type==='income'?'รายรับ':'รายจ่าย')+'จริงเดือนนี้')}</section>`;
}
function cashPoints(){
  const rows=actual_(S,month),days=Number(dayInMonth_(month,31).slice(-2)),out=[];let income=0,expense=0,start=1;
  for(let d=1;d<=days;d++){rows.filter(t=>Number(t.date.slice(-2))===d).forEach(t=>{if(t.type==='income')income+=t.amount;if(t.type==='expense')expense+=t.amount;});
    if(chartMode==='day'||d%7===0||d===days){out.push({start,day:d,income,expense,net:income-expense});income=0;expense=0;start=d+1;}}
  return out;
}
function cashChart(){
  const pts=cashPoints(),all=pts.flatMap(p=>[p.income,p.expense,p.net]),low=Math.min(0,...all),high=Math.max(100,...all),span=high-low;
  const x=i=>22+i/Math.max(1,pts.length-1)*456,y=v=>154-(v-low)/span*130,w=Math.min(14,180/pts.length),base=y(0);
  const line=pts.map((p,i)=>`${i?'L':'M'} ${x(i)} ${y(p.net)}`).join(' ');
  return `<section class="card wide flow-card"><div class="cardhead"><div><div class="eyebrow">01 / MONEY PULSE</div><h2>กระแสเงินของคุณ</h2></div><div class="segmented"><button id="dailyChart" class="${chartMode==='day'?'selected':''}">รายวัน</button><button id="weeklyChart" class="${chartMode==='week'?'selected':''}">รายสัปดาห์</button></div></div><div class="chart-key"><span style="color:var(--blue)">แท่งรายรับ (กว้าง)</span><span style="color:#849bcf">แท่งรายจ่าย (ซ้อน)</span><span style="color:var(--gold)">เส้นสุทธิ</span></div><div class="chart-area"><svg id="cashSvg" class="chart" viewBox="0 0 500 190" role="img" aria-label="กราฟแท่งรายรับ รายจ่าย และเส้นสุทธิของแต่ละช่วง หน่วยบาท"><defs><linearGradient id="barBlue" x2="0" y2="1"><stop stop-color="#64beff"/><stop offset="1" stop-color="#2859c8" stop-opacity=".4"/></linearGradient><filter id="glowGold" x="-50%" y="-100%" width="200%" height="300%"><feGaussianBlur stdDeviation="3.2" result="blur"/><feMerge><feMergeNode in="blur"/><feMergeNode in="SourceGraphic"/></feMerge></filter></defs>${[0,.5,1].map(f=>{const v=low+span*f,yy=y(v);return `<line x1="22" x2="478" y1="${yy}" y2="${yy}" stroke="var(--line)" stroke-dasharray="3 5"/><text x="22" y="${yy-5}">${baht(v)}</text>`;}).join('')}<line x1="18" x2="482" y1="${base}" y2="${base}" stroke="var(--muted)" opacity=".5"/>${pts.map((p,i)=>`<g><title>วันที่ ${p.start}–${p.day}: รับ ${cash(p.income)} จ่าย ${cash(p.expense)} สุทธิ ${cash(p.net)}</title><rect class="glow-bar" x="${x(i)-w}" y="${y(p.income)}" width="${w*2}" height="${Math.max(0,base-y(p.income))}" rx="2" fill="url(#barBlue)"/><rect x="${x(i)-w*.55}" y="${y(p.expense)}" width="${w*1.1}" height="${Math.max(0,base-y(p.expense))}" rx="2" fill="#849bcf" opacity=".65"/></g>`).join('')}<path d="${line} L ${x(pts.length-1)} ${base} L ${x(0)} ${base} Z" fill="#dcb96c" opacity=".08"/><path d="${line}" fill="none" stroke="var(--gold)" stroke-width="2.4" stroke-linejoin="round" filter="url(#glowGold)"/>${pts.filter((p,i)=>chartMode==='week'||p.net!==0).map(p=>`<circle cx="${x(pts.indexOf(p))}" cy="${y(p.net)}" r="2.8" fill="var(--gold)"/>`).join('')}<text x="22" y="182">${pts[0].day}</text><text x="245" y="182">วันที่</text><text x="466" y="182">${pts[pts.length-1].day}</text><line id="chartCursor" x1="478" x2="478" y1="18" y2="158" stroke="var(--muted)" stroke-dasharray="3 4"/></svg></div><input id="chartRange" type="range" min="0" max="${pts.length-1}" value="${pts.length-1}" aria-label="เลือกวันในกราฟ"><div id="chartTip" class="chart-tip"></div><small>ยอดของแต่ละช่วง ไม่ใช่ยอดสะสม · สุทธิ = รายรับ − รายจ่าย · ไม่รวมออมและโอนตนเอง</small></section>`;
}
function radarData(){
  const rows=actual_(S,month).filter(t=>t.type==='expense'),alloc=S.Budgets[month]?.allocations||{};
  const ranked=values_(S,'Categories').filter(c=>c.type==='expense').map(c=>({name:c.name,icon:c.icon,spent:total_(rows.filter(t=>t.category===c.id)),budget:alloc[c.id]||0})).sort((a,b)=>Math.max(b.spent,b.budget)-Math.max(a.spent,a.budget));
  if(ranked.length<=6)return ranked;
  return ranked.slice(0,5).concat([{name:'หมวดอื่น ๆ',icon:'📦',spent:ranked.slice(5).reduce((n,c)=>n+c.spent,0),budget:ranked.slice(5).reduce((n,c)=>n+c.budget,0)}]);
}
function radarChart(){
  const ds=radarData(),max=Math.max(100,...ds.flatMap(d=>[d.spent,d.budget])),n=ds.length;
  const pt=(i,v,r=80)=>{const t=-Math.PI/2+i*2*Math.PI/n;return [160+Math.cos(t)*r*v,116+Math.sin(t)*r*v];},points=(key,f)=>ds.map((d,i)=>pt(i,key?d[key]/max:f).join(',')).join(' ');
  return `<section class="card wide radar-card"><div class="cardhead"><div><div class="eyebrow">02 / SPENDING RADAR</div><h2>รายจ่ายเทียบแผนงบ</h2></div><span class="pill">${esc(monthLabel(month))}</span></div><div class="radar-layout"><svg class="radar" viewBox="0 0 320 235" role="img" aria-label="เรดาร์รายจ่ายจริงเทียบงบ แต่ละแกนใช้สเกลเงินบาทเดียวกัน">${[.25,.5,.75,1].map(f=>`<polygon points="${points(null,f)}" fill="none" stroke="var(--line)"/>`).join('')}${ds.map((d,i)=>{const p=pt(i,1),l=pt(i,1,103);return `<line x1="160" y1="116" x2="${p[0]}" y2="${p[1]}" stroke="var(--line)"/><text x="${l[0]}" y="${l[1]}" text-anchor="middle" dominant-baseline="middle" fill="var(--muted)" font-size="10">${esc(d.icon+' '+d.name)}</text>`;}).join('')}<polygon points="${points('budget')}" fill="#dcb96c14" stroke="var(--gold)" stroke-width="1.5" stroke-dasharray="4 4"/><polygon class="radar-glow" points="${points('spent')}" fill="#459fff30" stroke="var(--blue)" stroke-width="2"/>${ds.map((d,i)=>{const p=pt(i,d.spent/max);return `<circle cx="${p[0]}" cy="${p[1]}" r="3" fill="var(--blue)"/>`;}).join('')}</svg><div class="radar-details"><div class="chart-key"><span class="accent">จริง</span><span style="color:var(--gold)">งบ</span></div>${ds.map(d=>`<div class="radar-row"><span>${esc(d.icon+' '+d.name)}</span><b>${cash(d.spent)}<small> / ${cash(d.budget)}</small></b></div>`).join('')}</div></div><p class="muted" style="font-size:11px">วงนอก = ${cash(max)} ทุกแกน · ${S.Budgets[month]?'เส้นทองคืองบ เส้นน้ำเงินคือรายจ่ายจริง':'ยังไม่ตั้งงบ เส้นงบจะแสดงเป็นศูนย์'} · ไม่ใช่คะแนนสุขภาพการเงิน</p></section>`;
}

function monthDebts(){return values_(S,'Debts').map(d=>({d,m:debtMonth_(S,d,month,meta.today)}));}
function dashboard(){const p=S.Users.main,a=summary_(S,month),budget=S.Budgets[month],limit=budget?Object.values(budget.allocations).reduce((a,b)=>a+b,0):0,ratio=limit?a.expense/limit*100:0,days=Number(dayInMonth_(month,31).slice(-2)),elapsed=month<meta.today.slice(0,7)?days:month>meta.today.slice(0,7)?0:Number(meta.today.slice(-2)),pace=ratio-elapsed/days*100;
  const dm=monthDebts(),due=dm.reduce((n,x)=>n+x.m.due,0),paid=dm.reduce((n,x)=>n+x.m.paid,0),unpaid=dm.reduce((n,x)=>n+x.m.unpaid,0),overdue=dm.reduce((n,x)=>n+x.m.overdue,0);
  return heading('สวัสดี, '+p.name+' 👋','YOUR PERSONAL FINANCE / OVERVIEW')+`<p class="muted" style="margin:-12px 0 20px">ทุกการเคลื่อนไหวของเงิน ในมุมมองเดียว</p><div class="grid"><section class="card hero wide"><div class="row between"><label>ยอดสุทธิประจำเดือน</label><span class="pill">◈ ${esc(monthLabel(month))}</span></div><div class="amount ${a.net<0?'negative':''}">${cash(a.net)}</div><span class="pill">${a.income?'เหลือ '+(a.net/a.income*100).toFixed(1)+'% ของรายรับ':'ยังไม่มีรายรับจริง'}</span><div class="hero-split"><div><small>↙ รายรับจริง</small><b class="positive">${cash(a.income)}</b></div><div><small>↗ รายจ่ายจริง</small><b class="negative">${cash(a.expense)}</b></div></div><p class="muted" style="font-size:11px;margin-top:14px">รายจ่าย ${a.income?(a.expense/a.income*100).toFixed(1)+'% ของรายรับ':'ยังคำนวณสัดส่วนไม่ได้'} · ออม ${cash(a.saving)} · โอนตนเอง ${cash(a.transfer)}<br>สุทธิ = รายรับ − รายจ่าย ไม่ใช่ยอดเงินในบัญชี • ออม/โอนตนเองไม่นับซ้ำเป็นรายจ่าย</p>${a.forecast?`<button class="ghost" data-page="transactions">◷ มี ${a.forecast} รายการรอยืนยัน</button>`:''}</section>${cashChart()}<section class="card"><div class="cardhead"><h2>จังหวะการใช้เงิน</h2><span class="pill">SPENDING PACE</span></div><h1 class="accent">${limit?ratio.toFixed(0)+'% ของงบ':'ยังไม่ตั้งงบ'}</h1><p style="text-align:center">${!limit?'ตั้งงบเพื่อเริ่มติดตาม':pace>10?'ใช้เงินเร็วกว่าแผน':pace< -10?'ใช้เงินช้ากว่าแผน':'ใช้เงินตามแผน'}</p><p class="muted" style="text-align:center;font-size:12px">ผ่านไป ${(elapsed/days*100).toFixed(0)}% ของเดือน · งบ ${cash(limit)}</p><button class="ghost" data-page="budget">ดูแผนงบ →</button></section><section class="card"><div class="cardhead"><h2>หนี้ที่ต้องจ่ายเดือนนี้</h2><span class="cat-icon">💳</span></div><h1>${cash(due)}</h1>${progress(due?Math.min(paid,due)/due*100:0)}<div class="metrics"><div><small>จ่ายแล้ว</small><b class="positive">${baht(paid)}</b></div><div><small>ยังไม่จ่าย</small><b>${baht(unpaid)}</b></div><div><small>เลยกำหนด</small><b class="negative">${baht(overdue)}</b></div></div><button class="ghost" data-page="debts">ดูรายละเอียดหนี้ →</button></section><section class="card wide"><div class="cardhead"><h2>รายการล่าสุด</h2><button class="ghost" data-page="transactions">ดูทั้งหมด →</button></div>${txRows(sortedRows().slice(0,5))}</section></div>`;
