function transactions(){const rows=sortedRows().filter(t=>(filters.type==='all'||t.type===filters.type)&&(!filters.category||t.category===filters.category)&&t.title.toLowerCase().includes(filters.q.toLowerCase()));const grouped={};rows.forEach(t=>(grouped[t.date]||=[]).push(t));
