function download(name,text,type){if(window.AndroidExport)return window.AndroidExport(name,text,type);const a=document.createElement('a'),url=URL.createObjectURL(new Blob([text],{type}));a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),10000);}
