function categoryGrid(type,selected){return values_(S,'Categories').filter(c=>c.type===type&&(c.active||c.id===selected)).map(c=>`<button type="button" data-choice="${c.id}" class="${c.id===selected?'selected':''}"><span>${esc(c.icon)}</span>${esc(c.name)}</button>`).join('');}
function wireCategories(form,initial){let chosen=initial;const redraw=()=>{const type=form.elements.type.value;const compatible=values_(S,'Categories').filter(c=>c.type===type&&(c.active||c.id===chosen));if(!compatible.some(c=>c.id===chosen))chosen=compatible[0]?.id||'';$('#categoryGrid').innerHTML=categoryGrid(type,chosen);form.elements.category.value=chosen;$$('[data-choice]').forEach(b=>b.onclick=()=>{chosen=b.dataset.choice;form.elements.category.value=chosen;$$('[data-choice]').forEach(x=>x.classList.toggle('selected',x===b));delete form.dataset.requestId;});};form.elements.type.onchange=redraw;redraw();}
function editTransaction(existing,draftIndex){
  const uploadedNew=[];let selectedPhotos=[];const t=existing||{id:uid(),title:'',amount:0,type:'expense',category:'food',date:meta.today,time:new Date().toLocaleTimeString('en-GB',{timeZone:'Asia/Bangkok',hour:'2-digit',minute:'2-digit'}),status:'actual',note:'',receiptIds:[]},isOld=!!S.Transactions[t.id],debt=t.debtId?S.Debts[t.debtId]:null;
  modal(draftIndex!==undefined?'ตรวจสลิป '+(draftIndex+1)+' / '+activeDrafts.length:isOld?'รายละเอียดรายการ':'บันทึกรายการ',`<form id="txForm">${draftIndex!==undefined?`<img class="receipt-preview" alt="สลิปที่กำลังตรวจ" src="data:${draftImages[draftIndex].mime};base64,${draftImages[draftIndex].data}"><p class="notice warn">${esc(t.warning||'ตรวจสอบทุกช่อง โดยเฉพาะทิศทางเงิน')}</p>`:''}${debt?`<p class="notice">💳 ${esc(debt.name)} • แก้ไขยอดแล้วหนี้คงเหลือคำนวณใหม่</p><input type="hidden" name="type" value="expense"><input type="hidden" name="category" value="debt">`:selectField('ประเภทรายการ','type',typeOptions(),t.type)+'<input type="hidden" name="category"><div class="icon-grid" id="categoryGrid"></div>'}${field('ชื่อรายการ','title',t.title,'text','maxlength="100" required')}${moneyField('จำนวนเงิน (บาท)','amount',t.amount,false)}${debt?`<div class="formgrid"><small>ยอดจ่ายลดหนี้คงเหลือ ไม่มีการคำนวณดอกเบี้ยเพิ่ม${t.interest?' · รายการเก่าคงส่วนดอกเบี้ยที่เคยบันทึก '+cash(t.interest):''}</small></div>${field('ชำระสำหรับงวด','period',t.period||month,'month','required min="2000-01" max="2099-12"')}`:''}<div class="formgrid">${field('วันที่ ค.ศ.','date',t.date,'date','required min="2000-01-01" max="2099-12-31"')}${field('เวลาไทย','time',t.time,'time','required')}</div>${debt?'<input type="hidden" name="status" value="actual">':selectField('สถานะ','status',[['actual','เกิดขึ้นจริงแล้ว'],['forecast','คาดการณ์ / รอยืนยัน']],t.status)}<label class="field"><span>หมายเหตุ</span><textarea name="note" maxlength="500">${esc(t.note||'')}</textarea></label>${t.type==='saving'||t.type==='transfer'?'<p class="notice">รายการนี้ไม่นับเป็นรายรับหรือรายจ่ายใหม่</p>':''}${draftIndex===undefined?'<label class="field"><span>เพิ่มรูปแนบ JPG/PNG (รวมไม่เกิน 5 รูป)</span><input id="txPhotos" type="file" accept="image/jpeg,image/png" multiple></label>':''}<div id="receiptLinks">${(t.receiptIds||[]).map((id,i)=>`<button type="button" data-view-file="${esc(id)}">ดูรูป ${i+1}</button>`).join('')}</div>${(t.receiptIds||[]).length?'<label class="check"><input type="checkbox" name="removeReceipts">นำรูปแนบออกจากรายการ (ไฟล์ยังอยู่ในเครื่อง)</label>':''}<div class="actions"><button type="submit" class="primary">${t.status==='forecast'?'บันทึก / เปลี่ยนสถานะ':'บันทึกรายการ'}</button>${isOld?'<button id="deleteTx" type="button" class="danger">ลบ</button>':''}${draftIndex!==undefined?'<button id="skipDraft" type="button">ข้ามรูปนี้</button>':''}</div></form>`);
  if(!debt)wireCategories($('#txForm'),t.category);
  $('#txPhotos')?.addEventListener('change',e=>{selectedPhotos=Array.from(e.target.files);uploadedNew.length=0;});
  $$('[data-view-file]').forEach(b=>b.onclick=()=>safely(async()=>{const r=await rpc('file',{id:b.dataset.viewFile});const im=document.createElement('img');im.className='receipt-preview';im.alt='รูปสลิป';im.src=r.url;b.replaceWith(im);},b));
  bindForm('txForm',async(v,f)=>{
    if(v.category==='debt'&&!debt)throw new Error('กรุณาใช้หน้าหนี้สิน → บันทึกจ่ายงวดนี้ เพื่อผูกเงินต้น');
    const value={...t,...v,amount:satang(v.amount),principal:debt?satang(v.amount)-(t.interest||0):0,interest:debt?(t.interest||0):0,receiptIds:v.removeReceipts?[]:(t.receiptIds||[])};
    const duplicate=values_(S,'Transactions').find(x=>x.id!==t.id&&x.date===value.date&&x.amount===value.amount&&x.type===value.type&&x.status===value.status);if(duplicate&&!confirm('อาจซ้ำกับ “'+duplicate.title+'” วันที่เดียวกันและยอดเท่ากัน ยืนยันว่าเป็นคนละรายการหรือไม่?'))return;
    if(draftIndex!==undefined && retainImages && !value.receiptIds.length){const image=draftImages[draftIndex];if(!image.savedId)image.savedId=(await rpc('upload',{...image,purpose:'receipt',requestId:'image_'+t.id})).id;value.receiptIds=[image.savedId];t.receiptIds=value.receiptIds;}
    if(draftIndex===undefined && selectedPhotos.length){
      if(value.receiptIds.length+selectedPhotos.length>5)throw new Error('รูปแนบรวมต้องไม่เกิน 5 รูป');
      for(let i=0;i<selectedPhotos.length;i++){if(!uploadedNew[i]){const data=await readImage(selectedPhotos[i]);const r=await rpc('upload',{...data,purpose:'receipt',requestId:'attachment_'+t.id+'_'+i+'_'+selectedPhotos[i].lastModified});uploadedNew[i]=r.id;}}
      value.receiptIds=[...value.receiptIds,...uploadedNew];
    }
    await save('Transactions',t.id,value,f);if(draftIndex!==undefined){activeDrafts[draftIndex].done=true;nextDraft();}else closeModal();
  });
  $('#deleteTx')?.addEventListener('click',e=>safely(()=>removeEntity('Transactions',t.id),e.currentTarget));$('#skipDraft')?.addEventListener('click',()=>{activeDrafts[draftIndex].done=true;nextDraft();});
}
