function renderWelcome(){const w=welcome;$('#main').innerHTML=`<section class="welcome card"><div class="brandmark">฿</div><div class="eyebrow">WELCOME TO YOUR NEXT CHAPTER</div><h1>${welcomeStep===1?'เงินของคุณ เรื่องของคุณ':welcomeStep===2?'วางเป้าเล็ก ๆ ให้ตัวเอง':'พร้อมเริ่มต้นแล้ว'}</h1><p class="muted" style="margin:10px 0 25px">${welcomeStep===1?'เริ่มจากทำความรู้จักกันนิดหนึ่ง':welcomeStep===2?'ยังไม่แน่ใจ ใส่ 0 แล้วกลับมาแก้ภายหลังได้':'ตรวจข้อมูลก่อนเริ่มจัดการเงิน'}</p><div class="stepper">${[1,2,3].map(i=>`<i class="${i<=welcomeStep?'on':''}"></i>`).join('')}</div><form id="welcomeForm">${welcomeStep===1?field('ชื่อหรือชื่อเล่น','name',w.name,'text','required maxlength="60"')+occupations(w.occupations)+`<button type="button" id="welcomeAvatar" style="margin-top:18px">${w.avatarId?'✓ มีรูปแล้ว เปลี่ยนรูป':'เพิ่มรูปโปรไฟล์ (ข้ามได้)'}</button>`:welcomeStep===2?moneyField('รายรับคาดการณ์ต่อเดือน','expectedIncome',w.expectedIncome)+'<input type="hidden" name="savingPercent" value="0">':`<h2>${esc(w.name)}</h2><p>${esc(w.occupations.join(' · '))}</p><p class="notice">รายรับคาดการณ์ ${cash(w.expectedIncome)} / เดือน<br>ระบบช่วยแนะนำเงินเก็บในหน้าแผนงบ<br>ข้อมูลส่วนตัวในเครื่องนี้ · THB · เวลาไทย</p>`}<div class="actions">${welcomeStep>1?'<button id="welcomeBack" type="button">ย้อนกลับ</button>':''}<button type="submit" class="primary">${welcomeStep===3?'เริ่มจัดการเงินของฉัน':'ถัดไป →'}</button></div></form></section>`;
  $('#welcomeAvatar')?.addEventListener('click',()=>chooseAvatar(async id=>{welcome.avatarId=id;renderWelcome();}));$('#welcomeBack')?.addEventListener('click',()=>{welcomeStep--;renderWelcome();});
  bindForm('welcomeForm',async(v,f)=>{if(welcomeStep===1){w.name=v.name;w.occupations=new FormData(f).getAll('occupation');if(!w.occupations.length)throw new Error('เลือกอาชีพอย่างน้อยหนึ่งอย่าง');welcomeStep++;renderWelcome();}else if(welcomeStep===2){w.expectedIncome=satang(v.expectedIncome);w.savingPercent=Number(v.savingPercent);welcomeStep++;renderWelcome();}else{await save('Users','main',w,f);}});
