async function readImage(file,maxSide=1400){if(!['image/jpeg','image/png'].includes(file.type))throw new Error('รองรับรูป JPG/PNG เท่านั้น กรุณาแปลง HEIC/PDF ก่อน');if(file.size>12000000)throw new Error('รูปต้นฉบับต้องไม่เกิน 12 MB');const url=URL.createObjectURL(file);try{const img=await new Promise((res,rej)=>{const im=new Image();im.onload=()=>res(im);im.onerror=()=>rej(new Error('อ่านรูปไม่ได้'));im.src=url;});const scale=Math.min(1,maxSide/Math.max(img.width,img.height)),cv=document.createElement('canvas');cv.width=Math.round(img.width*scale);cv.height=Math.round(img.height*scale);const cx=cv.getContext('2d');cx.fillStyle='#fff';cx.fillRect(0,0,cv.width,cv.height);cx.drawImage(img,0,0,cv.width,cv.height);const data=cv.toDataURL('image/jpeg',.86).split(',')[1];if(data.length>2200000)throw new Error('รูปหลังแปลงยังใหญ่เกิน 1.6 MB กรุณาย่อรูป');return {mime:'image/jpeg',data};}finally{URL.revokeObjectURL(url);}}
