/* Pure financial functions. All money is integer satang; dates are Gregorian ISO. */
const TABLES_ = ['Users','Transactions','Categories','Budgets','Recurring','Debts','DebtPayments','Settings'];
const COLORS_ = ['#FFB86B','#58B8FF','#B69CFF','#FF89BF','#FF6275','#8EABFF','#FFD56B','#58D9DB','#AABEFF','#39E6A3','#93A5B6'];
function fail_(message) { throw new Error(message); }
function text_(v, max, required) {
  if (typeof v !== 'string' || v.length > max || (required && !v.trim())) fail_('ข้อความไม่ถูกต้องหรือยาวเกินกำหนด');
  return v.trim();
}
function money_(v, zero) {
  if (!Number.isSafeInteger(v) || v < (zero ? 0 : 1) || v > 100000000000) fail_('จำนวนเงินไม่ถูกต้อง (ต้องเป็นจำนวนสตางค์เต็ม)');
  return v;
}
function num_(v, min, max) { if (typeof v !== 'number' || !Number.isFinite(v) || v < min || v > max) fail_('ตัวเลขนอกช่วงที่รองรับ'); return v; }
function date_(s) {
  if (typeof s !== 'string' || !/^20\d{2}-\d{2}-\d{2}$/.test(s) || new Date(s+'T00:00:00Z').toISOString().slice(0,10) !== s) fail_('วันที่ต้องเป็น ค.ศ. 2000–2099 และมีอยู่จริง');
  return s;
}
function month_(s) { if (typeof s !== 'string' || !/^20\d{2}-(0[1-9]|1[0-2])$/.test(s)) fail_('เดือนไม่ถูกต้อง'); return s; }
function dayInMonth_(m, day) { month_(m); return m+'-'+String(Math.min(day,new Date(Number(m.slice(0,4)),Number(m.slice(5)),0).getDate())).padStart(2,'0'); }
function nextMonth_(m, delta) { const d=new Date(m+'-01T00:00:00Z'); d.setUTCMonth(d.getUTCMonth()+(delta||1)); return d.toISOString().slice(0,7); }
function emptyState_() { return Object.fromEntries(TABLES_.map(t=>[t,Object.create(null)])); }
function values_(s,t) { return Object.values(s[t]); }
function actual_(s,m) { return values_(s,'Transactions').filter(t=>t.status==='actual' && (!m || t.date.slice(0,7)===m)); }
function categories_() {
  const exp=[['food','อาหาร','🍜'],['travel','เดินทาง','🚗'],['home','ที่พัก','🏠'],['shopping','ช้อปปิ้ง','🛍️'],['health','สุขภาพ','❤️'],['fun','บันเทิง','🎮'],['education','การศึกษา','📚'],['debt','ผ่อนหนี้','💳'],['give','โอนให้คนอื่น','↗️'],['saving','ออม','🐷'],['other','อื่น ๆ','📦']];
  const inc=[['salary','เงินเดือน','💼'],['freelance','ฟรีแลนซ์','💻'],['sales','ขายของ','🛒'],['received','โอนเข้า','💸'],['yield','ดอกเบี้ย / ปันผล','📈'],['incomeOther','อื่น ๆ','💰']];
  return exp.map((x,i)=>({id:x[0],name:x[1],icon:x[2],color:COLORS_[i],type:x[0]==='saving'?'saving':'expense',active:true})).concat(inc.map((x,i)=>({id:x[0],name:x[1],icon:x[2],color:COLORS_[i],type:'income',active:true})),[{id:'selfTransfer',name:'โอนระหว่างบัญชีตนเอง',icon:'🔁',color:'#58B8FF',type:'transfer',active:true}]);
}
function total_(rows,field) { return rows.reduce((a,x)=>a+(x[field||'amount']||0),0); }
function summary_(s,m) {
  const rows=actual_(s,m), income=total_(rows.filter(x=>x.type==='income')), expense=total_(rows.filter(x=>x.type==='expense'));
  return {income,expense,net:income-expense,saving:total_(rows.filter(x=>x.type==='saving')),transfer:total_(rows.filter(x=>x.type==='transfer')),forecast:values_(s,'Transactions').filter(x=>x.date.slice(0,7)===m && x.status==='forecast').length};
}
function paidPrincipal_(s,id,exclude) { return total_(actual_(s).filter(t=>t.debtId===id && t.id!==exclude),'principal'); }
function debtBalance_(s,d) { return Math.max(0,d.principal-paidPrincipal_(s,d.id)); }
function debtProjection_(balance,annualRate,payment) {
  let b=balance,interest=0,months=0;
  if (!b) return {months:0,interest:0,amortizes:true};
  for(;b>0 && months<600;months++) { const i=Math.round(b*annualRate/1200); if(payment<=i) return {months:null,interest:null,amortizes:false}; const p=Math.min(b,payment-i); b-=p; interest+=i; }
  return {months:b>0?null:months,interest:b>0?null:interest,amortizes:b===0};
}
function debtMonth_(s,d,m,today) {

  // Due basis uses payment period, not cash date. Cash totals use actual payment date.
  const previous=actual_(s).filter(t=>t.debtId===d.id && t.period<m);
  const opening=Math.max(0,d.principal-total_(previous,'principal'));
  const interest=0, due=dayInMonth_(m,d.dueDay)<d.start?0:Math.min(d.payment,opening);
  const paid=total_(actual_(s).filter(t=>t.debtId===d.id && t.period===m));
  const unpaid=Math.max(0,due-paid), date=dayInMonth_(m,d.dueDay);
  return {due,paid,unpaid,overdue:date<today?unpaid:0,date,interest};
}
function occurrenceDates_(r,today) {
  const out=[]; let m=r.start.slice(0,7), end=(r.end && r.end<today?r.end:today);
  for(let guard=0;guard<1200 && m<=end.slice(0,7);guard++,m=nextMonth_(m)) { const d=dayInMonth_(m,r.day); if(d>=r.start && d<=end) out.push(d); }
  return out;
}
function allocate_(s,m,income,savingPercent,today) {
  money_(income,true); num_(savingPercent,0,100); month_(m);
  const allocations={},fixed={}; values_(s,'Categories').filter(c=>c.type==='expense'&&c.active).forEach(c=>allocations[c.id]=0);
  const debt=values_(s,'Debts').reduce((n,d)=>n+debtMonth_(s,d,m,today).due,0); allocations.debt=debt;
  values_(s,'Recurring').filter(r=>r.active && r.type==='expense' && r.category!=='debt' && dayInMonth_(m,r.day)>=r.start && (!r.end || dayInMonth_(m,r.day)<=r.end)).forEach(r=>{fixed[r.category]=(fixed[r.category]||0)+r.amount; allocations[r.category]=(allocations[r.category]||0)+r.amount;});
  const saving=Math.round(income*savingPercent/100), reserved=debt+total_(Object.values(fixed).map(amount=>({amount})))+saving, remaining=Math.max(0,income-reserved);
  const history=actual_(s).filter(t=>t.date.slice(0,7)>=nextMonth_(m,-3)&&t.date.slice(0,7)<m && t.type==='expense'&&!t.debtId&&t.source!=='recurring'&&t.category!=='debt');
  const eligible=Object.keys(allocations).filter(k=>k!=='debt'), weights=eligible.map(k=>total_(history.filter(t=>t.category===k))), sum=weights.reduce((a,b)=>a+b,0);
  let assigned=0; eligible.forEach((k,i)=>{const part=i===eligible.length-1?remaining-assigned:Math.floor(remaining*(sum?weights[i]/sum:1/eligible.length)); allocations[k]+=part; assigned+=part;});
  return {month:m,expectedIncome:income,savingPercent,allocations,fixed,saving,reserved,shortfall:Math.max(0,reserved-income),basis:sum?'รายจ่ายจริงย้อนหลังไม่เกิน 3 เดือน (ไม่รวมรายการประจำและหนี้)':'แบ่งเท่ากันเพราะยังไม่มีข้อมูลย้อนหลัง'};
}
function validateEntity_(table,raw,s,id) {
  const v=raw||{}, out={id};
  if(table==='Users') {
    out.name=text_(v.name,60,true); if(!Array.isArray(v.occupations)||v.occupations.length<1||v.occupations.length>5) fail_('เลือกอาชีพอย่างน้อยหนึ่งอย่าง');
    out.occupations=v.occupations.map(x=>text_(x,40,true)); out.expectedIncome=money_(v.expectedIncome,true); out.savingPercent=num_(v.savingPercent,0,100); out.onboarded=true; out.avatarId=text_(v.avatarId||'',120,false);
    if(out.avatarId) ownedFile_(out.avatarId);
  } else if(table==='Settings') {
    if(!['dark','light','system'].includes(v.theme)) fail_('ธีมไม่ถูกต้อง'); out.theme=v.theme; out.notifyEnabled=!!v.notifyEnabled;
  } else if(table==='Categories') {
    out.name=text_(v.name,50,true); out.icon=text_(v.icon,12,true); if(!/^#[a-fA-F0-9]{6}$/.test(v.color)) fail_('สีไม่ถูกต้อง'); out.color=v.color;
    if(!['income','expense','saving','transfer'].includes(v.type)) fail_('ประเภทไม่ถูกต้อง'); out.type=v.type; out.active=!!v.active;
    if(s.Categories[id] && s.Categories[id].type!==out.type) fail_('แก้ไขประเภทหมวดเดิมไม่ได้ กรุณาสร้างหมวดใหม่');
    if(['debt','saving','selfTransfer'].includes(id)&&!out.active) fail_('หมวดระบบนี้ต้องเปิดใช้งาน');
    if(!out.active && values_(s,'Recurring').some(r=>r.active&&r.category===id)) fail_('พักรายการประจำที่ใช้หมวดนี้ก่อนปิดหมวด');
  } else if(table==='Transactions' || table==='Recurring') {
    out.title=text_(v.title,100,true); out.amount=money_(v.amount); out.type=v.type; out.category=text_(v.category,80,true);
    const c=s.Categories[out.category]; if(!c || c.type!==out.type || (!c.active && (!s[table][id]||s[table][id].category!==out.category))) fail_('หมวดหมู่ไม่ตรงกับประเภทหรือปิดใช้งาน');
    out.note=text_(v.note||'',500,false);
    if(table==='Recurring') {
      if(out.category==='debt') fail_('กรุณาบันทึกชำระหนี้ผ่านหน้าหนี้สิน');
      out.day=num_(v.day,1,31); if(!Number.isInteger(out.day)) fail_('วันที่ต้องเป็นจำนวนเต็ม'); out.start=date_(v.start); out.end=v.end?date_(v.end):'';
      if(out.end && out.end<out.start) fail_('วันสิ้นสุดต้องไม่ก่อนวันเริ่ม'); out.active=!!v.active;
    } else {
      out.date=date_(v.date); if(!/^([01]\d|2[0-3]):[0-5]\d$/.test(v.time||'')) fail_('เวลาไม่ถูกต้อง'); out.time=v.time;
      if(!['actual','forecast'].includes(v.status)) fail_('สถานะไม่ถูกต้อง'); out.status=v.status;
      const old=s.Transactions[id]; out.source=old?old.source:(v.source==='slip'?'slip':'manual'); out.recurrenceKey=old?old.recurrenceKey||'':'';
      out.receiptIds=Array.isArray(v.receiptIds)?v.receiptIds:[]; if(out.receiptIds.length>5) fail_('แนบได้สูงสุด 5 รูป'); out.receiptIds.forEach(ownedFile_);
      out.debtId=v.debtId||''; out.principal=0; out.interest=0; out.period='';
      if(out.debtId) {
        const d=s.Debts[out.debtId]; if(!d||out.type!=='expense'||out.category!=='debt'||out.status!=='actual') fail_('ข้อมูลการชำระหนี้ไม่ถูกต้อง');
        out.principal=money_(v.principal,true); out.interest=money_(v.interest,true); out.period=month_(v.period);
        if(out.principal+out.interest!==out.amount || out.principal> d.principal-paidPrincipal_(s,d.id,id)) fail_('เงินต้น + ดอกเบี้ยต้องเท่ากับยอดชำระ และเงินต้นต้องไม่เกินหนี้คงเหลือ');
        if(out.period<d.start.slice(0,7)||out.date<d.start) fail_('วันที่หรืองวดชำระก่อนเริ่มหนี้');
      } else if(out.category==='debt') fail_('ใช้ปุ่มบันทึกชำระจากหน้าหนี้สินเพื่อผูกยอดเงินต้น');
    }
  } else if(table==='Debts') {
    out.name=text_(v.name,80,true); out.icon=text_(v.icon||'💳',12,true); out.kind=text_(v.kind||'อื่น ๆ',40,true); out.principal=money_(v.principal); out.annualRate=num_(v.annualRate,0,100); out.payment=money_(v.payment); out.dueDay=num_(v.dueDay,1,31); if(!Number.isInteger(out.dueDay)) fail_('วันที่ไม่ถูกต้อง'); out.start=date_(v.start);
    if(!['reducing','manual'].includes(v.method)) fail_('วิธีคิดดอกเบี้ยไม่ถูกต้อง'); out.method=v.method;
    if(out.principal<paidPrincipal_(s,id)) fail_('เงินต้นเริ่มต้นต่ำกว่าเงินต้นที่จ่ายแล้ว');
    if(actual_(s).some(t=>t.debtId===id && (t.date<out.start || t.period<out.start.slice(0,7)))) fail_('วันเริ่มหนี้ใหม่อยู่หลังประวัติชำระ');
  } else if(table==='Budgets') {
    out.month=month_(v.month); if(id!==out.month) fail_('รหัสงบต้องตรงเดือน'); out.expectedIncome=money_(v.expectedIncome,true); out.savingPercent=num_(v.savingPercent,0,100); out.allocations={};
