}

function debtAlerts_(s,today){
 const limit=new Date(today+'T00:00:00Z');limit.setUTCDate(limit.getUTCDate()+3);const end=limit.toISOString().slice(0,10),out=[];
 values_(s,'Debts').forEach(d=>{if(!debtBalance_(s,d))return;for(let m=d.start.slice(0,7),guard=0;m<=end.slice(0,7)&&guard<1200;m=nextMonth_(m),guard++){const x=debtMonth_(s,d,m,today);if(x.unpaid&&x.date<=end)out.push({id:d.id,date:x.date,unpaid:x.unpaid});}});return out.sort((a,b)=>a.date.localeCompare(b.date));
}

