 const r=b.record;if(!r.state||!r.requests||!r.slips||!Array.isArray(r.history)||b.images.length>10000)throw Error('โครงสร้างไฟล์ไม่ถูกต้อง');
 if(Object.keys(r.requests).length>20000)throw Error('ประวัติเกินขนาด');for(const id of Object.keys(r.requests))offlineId_(id);for(const id of Object.keys(r.slips))offlineId_(id);
