 const d=text.match(/\b(\d{1,2})[\/-](\d{1,2})[\/-](\d{4})\b/);if(d){let y=+d[3];if(y>2400)y-=543;const s=y+'-'+d[2].padStart(2,'0')+'-'+d[1].padStart(2,'0');try{date=date_(s);}catch(e){}}
