 private boolean fullAccess(){return checkSelfPermission(Build.VERSION.SDK_INT>=33?Manifest.permission.READ_MEDIA_IMAGES:Manifest.permission.READ_EXTERNAL_STORAGE)==PackageManager.PERMISSION_GRANTED;}
 private boolean someAccess(){return fullAccess()||(Build.VERSION.SDK_INT>=34&&checkSelfPermission(Manifest.permission.READ_MEDIA_VISUAL_USER_SELECTED)==PackageManager.PERMISSION_GRANTED);}
 private void requestGallery(){runOnUiThread(()->{if(fullAccess()){scan();return;}new AlertDialog.Builder(this).setTitle("อ่านสลิปจากคลังภาพ").setMessage("แอปจะอ่านภาพของเดือนปัจจุบันเมื่อเข้าแอป ประมวลผลในเครื่อง ไม่ส่งรูปออกไป และให้คุณตรวจทานก่อนบันทึก เลือกอนุญาตรูปทั้งหมดเพื่อให้ตรวจได้ครบ หรือเลือกบางรูปได้ตามต้องการ").setPositiveButton("ดำเนินการต่อ",(d,w)->{getPreferences(0).edit().putBoolean("asked",true).apply();permission.launch(Build.VERSION.SDK_INT>=34?new String[]{Manifest.permission.READ_MEDIA_IMAGES,Manifest.permission.READ_MEDIA_VISUAL_USER_SELECTED}:new String[]{Build.VERSION.SDK_INT>=33?Manifest.permission.READ_MEDIA_IMAGES:Manifest.permission.READ_EXTERNAL_STORAGE});}).setNegativeButton("ภายหลัง",(d,w)->getPreferences(0).edit().putBoolean("asked",true).apply()).show();});}
 public final class Bridge {
  @JavascriptInterface public void ready(){runOnUiThread(()->{if(ready)return;ready=true;if(!someAccess()&&!getPreferences(0).getBoolean("asked",false))requestGallery();else scan();});}
  @JavascriptInterface public void scanGallery(){requestGallery();}
  @JavascriptInterface public void stopScan(){stop=true;}
  @JavascriptInterface public void ocr(String id,String base64){io.execute(()->{try{if(base64.length()>2200000)throw new IOException("รูปใหญ่เกินกำหนด");byte[] data=android.util.Base64.decode(base64,android.util.Base64.DEFAULT);Bitmap b=BitmapFactory.decodeByteArray(data,0,data.length);if(b==null)throw new IOException("อ่านภาพไม่ได้");try{reply(id,true,recognize(b));}finally{b.recycle();}}catch(Exception e){reply(id,false,"อ่านภาพไม่สำเร็จ กรุณากรอกเอง");}});}
  @JavascriptInterface public void photo(String id,String uri){io.execute(()->{try{if(!knownImages.contains(uri)||!someAccess())throw new IOException();Bitmap b=bitmap(Uri.parse(uri),1400);try(ByteArrayOutputStream out=new ByteArrayOutputStream()){b.compress(Bitmap.CompressFormat.JPEG,82,out);if(out.size()>1600000)throw new IOException();reply(id,true,new JSONObject().put("mime","image/jpeg").put("data",android.util.Base64.encodeToString(out.toByteArray(),android.util.Base64.NO_WRAP)));}finally{b.recycle();}}catch(Exception e){reply(id,false,"เปิดรูปไม่ได้ รูปอาจถูกลบหรือสิทธิ์เปลี่ยน กรุณาตรวจใหม่");}});}
  @JavascriptInterface public void exportDocument(String name,String text,String type){if(text.length()>50000000){notice("ไฟล์ใหญ่เกิน 50 MB");return;}runOnUiThread(()->{if(exportText!=null){notice("กำลังเลือกที่บันทึกไฟล์ก่อนหน้า");return;}exportText=text;try{export.launch(new Intent(Intent.ACTION_CREATE_DOCUMENT).addCategory(Intent.CATEGORY_OPENABLE).setType("text/csv".equals(type)?"text/csv":"application/json").putExtra(Intent.EXTRA_TITLE,name.replaceAll("[^a-zA-Z0-9._-]","_")));}catch(Exception e){exportText=null;notice("เปิดหน้าบันทึกไม่ได้");}});}
 }
 private void initOCR()throws IOException{if(tess!=null)return;File base=new File(getFilesDir(),"tesseract"),data=new File(base,"tessdata");if(!data.exists()&&!data.mkdirs())throw new IOException();for(String lang:new String[]{"tha","eng"}){File out=new File(data,lang+".traineddata");if(!out.exists()){File temp=new File(data,lang+".tmp");try(InputStream in=getAssets().open("tessdata/"+lang+".traineddata");OutputStream dest=new FileOutputStream(temp)){byte[] b=new byte[65536];int n;while((n=in.read(b))!=-1)dest.write(b,0,n);}if(!temp.renameTo(out))throw new IOException();}}TessBaseAPI t=new TessBaseAPI();if(!t.init(base.getAbsolutePath(),"tha+eng")){t.recycle();throw new IOException("OCR init");}tess=t;}
 private String recognize(Bitmap b)throws IOException{initOCR();tess.setImage(b);try{return tess.getUTF8Text();}finally{tess.clear();}}
 private Bitmap bitmap(Uri uri,int side)throws IOException{
  if(Build.VERSION.SDK_INT>=28)return ImageDecoder.decodeBitmap(ImageDecoder.createSource(getContentResolver(),uri),(decoder,info,source)->{int w=info.getSize().getWidth(),h=info.getSize().getHeight();double scale=Math.min(1.0,(double)side/Math.max(w,h));decoder.setTargetSize(Math.max(1,(int)(w*scale)),Math.max(1,(int)(h*scale)));decoder.setAllocator(ImageDecoder.ALLOCATOR_SOFTWARE);});
  BitmapFactory.Options o=new BitmapFactory.Options();o.inJustDecodeBounds=true;try(InputStream in=getContentResolver().openInputStream(uri)){BitmapFactory.decodeStream(in,null,o);}o.inSampleSize=1;while(Math.max(o.outWidth,o.outHeight)/o.inSampleSize>side*2)o.inSampleSize*=2;o.inJustDecodeBounds=false;try(InputStream in=getContentResolver().openInputStream(uri)){Bitmap b=BitmapFactory.decodeStream(in,null,o);if(b==null)throw new IOException();return b;}
 }
 private String hash(Uri uri)throws Exception{MessageDigest d=MessageDigest.getInstance("SHA-256");try(InputStream in=getContentResolver().openInputStream(uri)){if(in==null)throw new IOException();byte[] b=new byte[65536];int n;while((n=in.read(b))!=-1){if(stop||destroyed)throw new IOException();d.update(b,0,n);}}StringBuilder s=new StringBuilder();for(byte b:d.digest())s.append(String.format(Locale.ROOT,"%02x",b));return s.toString();}
 private void scan(){if(!ready||destroyed)return;if(!someAccess()){progress(0,0,"ยังไม่ได้อนุญาตคลังภาพ แตะปุ่มอ่านสลิปเพื่ออนุญาต");return;}if(!scanning.compareAndSet(false,true))return;stop=false;io.execute(()->{
  JSONArray found=new JSONArray();Set<String> hashes=new HashSet<>();int done=0,total=0,errors=0;boolean partial=!fullAccess();
  try{if(cache==null){cache=openOrCreateDatabase("ocr-cache.db",MODE_PRIVATE,null);cache.execSQL("CREATE TABLE IF NOT EXISTS scans (uri TEXT PRIMARY KEY, signature TEXT, hash TEXT, text TEXT)");}
   ZonedDateTime start=LocalDate.now(ZoneId.of("Asia/Bangkok")).withDayOfMonth(1).atStartOfDay(ZoneId.of("Asia/Bangkok"));long from=start.toInstant().toEpochMilli(),to=start.plusMonths(1).toInstant().toEpochMilli();
   String selection="(datetaken >= ? AND datetaken < ?) OR ((datetaken IS NULL OR datetaken <= 0) AND date_added >= ? AND date_added < ?)";
   try(Cursor c=getContentResolver().query(MediaStore.Images.Media.EXTERNAL_CONTENT_URI,new String[]{"_id","date_modified","_size","_display_name"},selection,new String[]{""+from,""+to,""+(from/1000),""+(to/1000)},"date_added DESC")){
    if(c==null)throw new IOException();total=c.getCount();progress(0,total,"กำลังตรวจภาพเดือนนี้ "+total+" รูป"+(partial?" (เฉพาะรูปที่อนุญาต)":""));
    while(c.moveToNext()&&!stop&&!destroyed){Uri uri=ContentUris.withAppendedId(MediaStore.Images.Media.EXTERNAL_CONTENT_URI,c.getLong(0));String key=uri.toString(),signature=c.getLong(1)+":"+c.getLong(2),text=null,digest=null;knownImages.add(key);
     try{try(Cursor row=cache.rawQuery("SELECT hash,text FROM scans WHERE uri=? AND signature=?",new String[]{key,signature})){if(row.moveToFirst()){digest=row.getString(0);text=row.getString(1);}}
      if(text==null){digest=hash(uri);Bitmap b=bitmap(uri,2000);try{text=recognize(b);}finally{b.recycle();}ContentValues v=new ContentValues();v.put("uri",key);v.put("signature",signature);v.put("hash",digest);v.put("text",text);cache.insertWithOnConflict("scans",null,v,SQLiteDatabase.CONFLICT_REPLACE);}
      if(text.matches("(?is).*(โอน|ชำระ|ธนาคาร|บาท|THB|transfer|payment|bank).*")&&text.matches("(?s).*\\d+[.,]\\d{2}.*")&&hashes.add(digest))found.put(new JSONObject().put("id",digest).put("uri",key).put("name",c.getString(3)).put("text",text));
     }catch(Exception e){errors++;}done++;progress(done,total,"ตรวจภาพ "+done+" / "+total+(partial?" • เฉพาะรูปที่อนุญาต":""));
    }
   }
   js("window.galleryResults("+found+")");progress(done,total,(stop?"หยุดตรวจแล้ว":"ตรวจเดือนนี้แล้ว")+" "+done+" / "+total+" รูป • พบ "+found.length()+" รูปรอตรวจ"+(errors>0?" • อ่านไม่ได้ "+errors+" รูป":"")+(partial?" • สิทธิ์เฉพาะบางรูป":""));
  }catch(Exception e){progress(done,total,"ตรวจภาพไม่สำเร็จ โปรดตรวจสิทธิ์คลังภาพแล้วลองอีกครั้ง");}finally{scanning.set(false);}
 });}
 private void progress(int done,int total,String m){js("window.galleryProgress("+done+","+total+","+JSONObject.quote(m)+")");}
 private void reply(String id,boolean ok,Object v){js("window.ocrReply("+JSONObject.quote(id)+","+ok+","+(v instanceof JSONObject?v.toString():JSONObject.quote(String.valueOf(v)))+")");}
 private void js(String code){runOnUiThread(()->{if(!destroyed)web.evaluateJavascript(code,null);});}
 private void notice(String m){runOnUiThread(()->{if(!destroyed)Toast.makeText(this,m,Toast.LENGTH_LONG).show();});}
 @Override protected void onDestroy(){destroyed=true;stop=true;if(fileCallback!=null)fileCallback.onReceiveValue(null);web.removeJavascriptInterface("FinanceNative");web.destroy();io.execute(()->{if(tess!=null)tess.recycle();if(cache!=null)cache.close();});io.shutdown();super.onDestroy();}
