for(const file of ['finance.js','offline.js'])vm.runInContext(fs.readFileSync(path.join(root,'app/src/main/assets',file),'utf8'),context);
const run=code=>vm.runInContext(code.replaceAll('\n','\\n'),context);let count=0;
function test(name,fn){fn();console.log('PASS',name);count++;}
test('Thai digits, BE date, amount, time',()=>{const p=run("parseSlip_('โอนเงินสำเร็จ\nจำนวนเงิน ๑,๒๕๐.๕๐ บาท\n19/10/2569 09:32\nค่าธรรมเนียม 0.00')");assert.equal(p.amount,125050);assert.equal(p.date,'2026-10-19');assert.equal(p.time,'09:32');});
test('fee and balance do not become transfer amount',()=>assert.equal(run("parseSlip_('transfer\namount 250.00 THB\nfee 12.00\nbalance 9000.00').amount"),25000));
test('ordinary photo text is not slip',()=>assert.equal(run("parseSlip_('meeting at 12:30').isSlip"),false));
test('invalid date is left for review',()=>assert.equal(run("parseSlip_('โอน 123.00 บาท 31/02/2569').date"),''));
test('Thai month abbreviation',()=>assert.equal(run("parseSlip_('โอน 100.00 บาท 19 ต.ค. 69').date"),'2026-10-19'));
run("var r=offlineNew_();offlineRecord_=r;var transaction={id:'slip_testhash',title:'test expense',amount:12345,type:'expense',category:'food',date:'2026-10-19',time:'09:00',status:'actual',source:'slip',receiptIds:[],note:''};var request={requestId:'request1',table:'Transactions',id:transaction.id,revision:0,value:transaction};");
test('expense commit is idempotent',()=>{run('offlineMutate_(r,request);offlineMutate_(r,request)');assert.equal(run('Object.keys(r.state.Transactions).length'),1);assert.equal(run('r.history.length'),1);});
test('saved scan stays deduplicated after transaction deletion',()=>{run("offlineMutate_(r,{requestId:'delete1',table:'Transactions',id:transaction.id,revision:1,remove:true})");assert.equal(run("r.slips.testhash"),'saved');});
test('conflicting revision rejected',()=>assert.throws(()=>run("offlineMutate_(r,{...request,requestId:'conflict',revision:2})")));
test('reject invalid backup and prototype key',()=>{assert.throws(()=>run("offlineValidateBackup_({})"));assert.throws(()=>run("offlineId_('__proto__')"));});
